Certainly! Below is an example of how you might implement a Contextual Multi-Armed Bandit (CMAB) algorithm using Object-Oriented Programming (OOP) principles in Python. This implementation will use three different models to make decisions based on the context provided.

```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        # Simple linear regression with L2 regularization
        self.weights = np.linalg.inv(X.T @ X + 0.1 * np.eye(X.shape[1])) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(X.shape[0], 1)

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.rewards = {model: [] for model in models}
        self.contexts = []
        self.actions = []

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            action = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            action = np.argmax(predictions)

        return action

    def update(self, context, action, reward):
        self.contexts.append(context)
        self.actions.append(action)
        self.rewards[self.models[action]].append(reward)

        # Update each model with the new data point
        for i, model in enumerate(self.models):
            if len(self.rewards[model]) > 0:
                X = np.array(self.contexts).reshape(-1, 1)
                y = np.array(self.rewards[model])
                model.fit(X, y)

# Example usage
if __name__ == "__main__":
    # Create some dummy data
    contexts = np.random.rand(100, 1)
    rewards = np.random.randint(0, 2, size=(100,))

    # Initialize models
    models = [LinearModel(), RandomModel(), LinearModel()]

    # Initialize bandit
    bandit = EpsilonGreedyBandit(models=models)

    # Run the bandit simulation
    for t in range(len(contexts)):
        action = bandit.select_action(contexts[t])
        reward = rewards[t]
        bandit.update(contexts[t], action, reward)

    print("Final weights:", [model.weights for model in models])
```

### Explanation:
- **Model Class**: A base class that defines the interface for all models.
- **LinearModel Class**: Implements a simple linear regression model.
- **RandomModel Class**: Implements a random model that always returns a random prediction.
- **EpsilonGreedyBandit Class**: Manages the selection of actions and updating of models based on the observed rewards.
- **Example Usage**: Demonstrates how to create instances of these classes and run a simulation.

This code provides a basic framework for implementing a CMAB algorithm using multiple models. You can extend it by adding more sophisticated models or modifying the update rules as needed.

