```

### Step 4: Implement the Chat Logic

Create a file named `app.js` and add the following content:

```javascript
async function loadModel() {
    const tokenizer = await huggingface.loadTokenizer('facebook/blenderbot-400m-distill');
    const model = await huggingface.loadModel('facebook/blenderbot-400m-distill');

    return { tokenizer, model };
}

function sendMessage() {
    const userInput = document.getElementById('user-input').value.trim();
    if (userInput === '') return;

    appendMessage(userInput, 'user-message');
    document.getElementById('user-input').value = '';

    // Generate response
    generateResponse(userInput).then(response => {
        appendMessage(response, 'bot-message');
    });
}

function appendMessage(message, className) {
    const chatContainer = document.getElementById('chat-container');
    const messageElement = document.createElement('div');
    messageElement.className = `message ${className}`;
    messageElement.textContent = message;
    chatContainer.appendChild(messageElement);
}

async function generateResponse(inputText) {
    const { tokenizer, model } = await loadModel();

    const encodedInput = tokenizer.encode(inputText, { addSpecialTokens: true });
    const tensorInput = tf.tensor([encodedInput]);

    const outputTensor = await model.predict(tensorInput);
    const decodedOutput = tokenizer.decode(outputTensor.dataSync());

    return decodedOutput;
}

// Initialize the application
document.addEventListener('DOMContentLoaded', () => {
    console.log('Application initialized.');
});
