    // Event listener for dragging the circle
    let isDragging = false;
    let startX, startY;

    circle.addEventListener('mousedown', function(e) {
        isDragging = true;
        startX = e.clientX - circle.offsetLeft;
        startY = e.clientY - circle.offsetTop;
