            const radius = Math.min(distance, 100);
            circle.style.width = `${radius}px`;
            circle.style.height = `${radius}px`;
            generateConcentricCircles(radius);
        }
    });

    document.addEventListener('mouseup', function() {
        isDragging = false;
    });
});
