    // Signal handler for demonstration purposes
    printf("Signal %d received\n", sig);
}

int main() {
    int fd;
    char buffer[1024];
    ssize_t bytes_read;

    // Open a file descriptor (for example, /dev/null)
    fd = open("/dev/null", O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set up a signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Perform a blocking read
        bytes_read = read(fd, buffer, sizeof(buffer));

        if (bytes_read == -1) {
            if (errno == EINTR) {
                // Handle the case where the read was interrupted by a signal
                printf("Read interrupted by signal, retrying...\n");
                continue;
            } else {
                // Handle other errors
                perror("read");
                break;
            }
        } else if (bytes_read == 0) {
            // End of file reached
            printf("End of file reached\n");
            break;
        } else {
            // Successfully read data
            printf("Read %zd bytes: %.*s\n", bytes_read, (int)bytes_read, buffer);
        }
    }

    // Close the file descriptor
    close(fd);

    return 0;
}
```

### Explanation:
1. **File Descriptor**: We open `/dev/null`, which is a special file that discards all data written to it and provides no data when read from.
2. **Signal Handler**: We set up a signal handler for `SIGINT` (which is typically sent when you press Ctrl+C). This handler simply prints a message indicating that a signal was received.
3. **Blocking Read**: Inside the loop, we perform a blocking read using `read`. If the read is interrupted by a signal, `read` will return `-1` and set `errno` to `EINTR`.
4. **Error Handling**: We check if `errno` is `EINTR` and handle it appropriately by printing a message and continuing the loop. For other errors, we print an error message and break out of the loop.
5. **End of File**: If `read` returns `0`, it means the end of the file has been reached, and we break out of the loop.
6. **Success Case**: If `read` successfully reads some data, we print the number of bytes read and the content of the buffer.

This example demonstrates how to robustly handle signals during blocking I/O operations in a Unix-like environment.

