import { createServer } from 'net';

class TCPServer {
    private server: any;

    constructor(private port: number) {
        this.server = createServer(this.handleConnection.bind(this));
        this.server.listen(port, () => {
            console.log(`TCP Server listening on port ${port}`);
        });
    }

    private handleConnection(socket: any) {
        socket.on('data', (data: Uint8Array) => {
            console.log(`Received data: ${data.toString()}`);
            // Echo back the received data
            socket.write(data);
        });

        socket.on('end', () => {
            console.log('Client disconnected');
        });

        socket.on('error', (err: Error) => {
            console.error('Socket error:', err);
        });
    }

    public close() {
        this.server.close(() => {
            console.log('TCP Server closed');
        });
    }
}

// Example usage
const server = new TCPServer(3000);
```

### TCP Client Implementation

```typescript
import { connect } from 'net';

class TCPClient {
    private socket: any;

    constructor(private host: string, private port: number) {
        this.socket = connect({ host, port }, () => {
            console.log(`Connected to ${host}:${port}`);
            const message = new Uint8Array([72, 101, 108, 108, 111]); // "Hello" in ASCII
            this.socket.write(message);
        });

        this.socket.on('data', (data: Uint8Array) => {
            console.log(`Received data: ${data.toString()}`);
        });

        this.socket.on('end', () => {
            console.log('Disconnected from server');
        });

        this.socket.on('error', (err: Error) => {
            console.error('Socket error:', err);
        });
    }

    public send(data: Uint8Array) {
        this.socket.write(data);
    }

    public close() {
        this.socket.end();
    }
}

// Example usage
const client = new TCPClient('localhost', 3000);
```

### Explanation

1. **TCPServer**:
   - The server listens on a specified port.
   - When a client connects, it reads the incoming data as a `Uint8Array` and echoes it back to the client.
   - The server can be closed manually by calling the `close()` method.

2. **TCPClient**:
   - The client connects to the server at a specified host and port.
   - It sends a `Uint8Array` containing the message "Hello" in ASCII.
   - The client receives the echoed data and logs it.
   - The client can be closed manually by calling the `close()` method.

### Running the Code

1. Start the server first:
   ```bash
   node server.ts
   ```

2. Then start the client:
   ```bash
   node client.ts
   ```

This will establish a connection between the client and server, and the client will send a message which the server will echo back.

