const { Readable } = require('stream');

class MyPullStream extends Readable {
  constructor(options) {
    super(options);
    this.data = [1, 2, 3, 4, 5];
    this.index = 0;
  }

  _read() {
    if (this.index < this.data.length) {
      const chunk = this.data[this.index++];
      this.push(chunk.toString());
    } else {
      this.push(null);
    }
  }
}

