   ```javascript
   // stores/sessionStore.js
   import { defineStore } from 'pinia';

   export const useSessionStore = defineStore('session', {
     state: () => ({
       sessionData: null,
     }),
     actions: {
       setSessionData(data) {
         this.sessionData = data;
       },
     },
   });
   ```

3. **Create a Query Function**:
   Use `@tanstack/vue-query` to create a query function that fetches data from `/get_session`.

   ```javascript
   // composable/useSessionQuery.js
   import { useQuery } from '@tanstack/vue-query';
   import axios from 'axios';

   export function useSessionQuery() {
     return useQuery(['session'], async () => {
       const response = await axios.get('/get_session');
       return response.data;
     });
   }
   ```

4. **Fetch Data and Update Pinia Store**:
   In your component or another composable, fetch the data using the query function and update the Pinia store with the selected keys.

   ```javascript
   // components/MyComponent.vue
   <template>
     <div>
       <!-- Your template code here -->
     </div>
   </template>

   <script setup>
   import { ref, onMounted } from 'vue';
   import { useSessionStore } from '@/stores/sessionStore';
   import { useSessionQuery } from '@/composables/useSessionQuery';

   const sessionStore = useSessionStore();
   const { data: sessionData, isLoading, isError } = useSessionQuery();

   onMounted(() => {
     if (sessionData && !isLoading && !isError) {
       // Select specific keys from the response
       const selectedKeys = {
         key1: sessionData.key1,
         key2: sessionData.key2,
       };

       // Update the Pinia store
       sessionStore.setSessionData(selectedKeys);
     }
   });
   </script>
   ```

5. **Access the Updated State**:
   You can now access the updated state in any component by using the Pinia store.

   ```javascript
   // components/AnotherComponent.vue
   <template>
     <div>
       {{ sessionStore.sessionData?.key1 }}
       {{ sessionStore.sessionData?.key2 }}
     </div>
   </template>

   <script setup>
   import { useSessionStore } from '@/stores/sessionStore';

   const sessionStore = useSessionStore();
   </script>
   ```

