Sure! Here's an example of how you can implement the Connect-4 game in Python:

```python
import numpy as np

# Define the size of the board
ROWS = 6
COLS = 7

# Initialize the board with empty spaces
board = np.zeros((ROWS, COLS), dtype=int)

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLS):
            if board[row][col] == 0:
                print(" ", end="|")
            elif board[row][col] == 1:
                print("X", end="|")
            else:
                print("O", end="|")
        print()

def is_valid_move(board, col):
    # Check if the move is valid (column is not full)
    return board[0][col] == 0

def drop_piece(board, col, player):
    # Drop the piece into the specified column
    for row in range(ROWS - 1, -1, -1):
        if board[row][col] == 0:
            board[row][col] = player
            break

def check_win(board, player):
    # Check if the player has won horizontally, vertically, or diagonally
    # Horizontal win
    for row in range(ROWS):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row][col + 1] == player and board[row][col + 2] == player and board[row][col + 3] == player:
                return True

    # Vertical win
    for row in range(ROWS - 3):
        for col in range(COLS):
            if board[row][col] == player and board[row + 1][col] == player and board[row + 2][col] == player and board[row + 3][col] == player:
                return True

    # Diagonal win (top-left to bottom-right)
    for row in range(ROWS - 3):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row + 1][col + 1] == player and board[row + 2][col + 2] == player and board[row + 3][col + 3] == player:
                return True

    # Diagonal win (bottom-left to top-right)
    for row in range(3, ROWS):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row - 1][col + 1] == player and board[row - 2][col + 2] == player and board[row - 3][col + 3] == player:
                return True

    return False

def main():
    player = 1  # Player 1 starts first
    while True:
        print_board(board)
        col = int(input(f"Player {player}, choose a column (0-{COLS - 1}): "))

        if is_valid_move(board, col):
            drop_piece(board, col, player)
            if check_win(board, player):
                print_board(board)
                print(f"Player {player} wins!")
                break
            player = 3 - player  # Switch players
        else:
            print("Invalid move. Try again.")

if __name__ == "__main__":
    main()
```

This code defines a simple Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The game checks for horizontal, vertical, and diagonal wins after each move. You can run this script in your Python environment to play against another human player.

